import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Bank dataset metadata contract","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/data/BANK-DATA-METADATA.html"}],["meta",{"property":"og:title","content":"Bank dataset metadata contract | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/data/BANK-DATA-METADATA.html"}],["meta",{"name":"twitter:title","content":"Bank dataset metadata contract | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"data/BANK-DATA-METADATA.md","filePath":"data/BANK-DATA-METADATA.md","lastUpdated":1794227887000}`),a={name:`data/BANK-DATA-METADATA.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="bank-dataset-metadata-contract" tabindex="-1">Bank dataset metadata contract <a class="header-anchor" href="#bank-dataset-metadata-contract" aria-label="Permalink to “Bank dataset metadata contract”">​</a></h1><p>The authoritative metadata index is <code>data/fd_options/fd_options.csv</code>. It describes the bank-level option dataset and is separate from each product row&#39;s bank-source fields.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th><th>Update rule</th></tr></thead><tbody><tr><td><code>dataset_updated_at</code></td><td>Date the bank&#39;s economic option data last materially changed (rate, tenor, minimum, payout terms, eligibility or another simulation input).</td><td>Update only when one or more economic product rows change. Leave blank when the actual change date is unknown.</td></tr><tr><td><code>dataset_reviewed_at</code></td><td>Date a maintainer last rechecked the bank&#39;s source material, whether or not the catalogue changed.</td><td>Update only after an actual source review. This is the input to freshness warnings.</td></tr><tr><td><code>dataset_schema_version</code></td><td>Version of the bank option CSV row schema/format.</td><td>Increment for schema-only migrations such as adding columns or renaming fields.</td></tr><tr><td><code>source_effective_date</code></td><td>Effective date stated by the bank for an individual product/rate row.</td><td>Preserve per product row; it is not the repository edit date.</td></tr></tbody></table><h2 id="migration-rules" tabindex="-1">Migration rules <a class="header-anchor" href="#migration-rules" aria-label="Permalink to “Migration rules”">​</a></h2><ol><li>A schema-only migration may add or reorder columns and increment <code>dataset_schema_version</code>.</li><li>A schema-only migration must preserve <code>dataset_updated_at</code> and <code>dataset_reviewed_at</code> exactly.</li><li>Do not infer either date from Git commit time, file modification time, release time or deployment time.</li><li>Do not set <code>dataset_updated_at</code> merely because the CSV gained columns or was reformatted.</li><li>A source recheck with no rate/term change updates <code>dataset_reviewed_at</code> only.</li><li>A confirmed economic-data change updates <code>dataset_updated_at</code>; update <code>dataset_reviewed_at</code> as well only if the source was rechecked at that time.</li><li>Blank dates mean unknown/unrecorded, not current. Never backfill dates from assumptions.</li></ol><p>The loader validates dates and schema versions, exposes normalized metadata through <code>bankDatasetRegistry</code>, and keeps the existing <code>dataset_reviewed_at</code> freshness behaviour. The metadata merge helper preserves both dates when only the schema version changes.</p><p>At introduction, existing bank review/data-change dates remain blank because no bank-by-bank source recheck was completed as part of this schema change. The schema version is recorded as <code>1</code>; this is not a claim that the rate data was updated.</p>`,7)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};